"""Critic Agent: Audits recommendations for source grounding, official portal validity, and hallucination prevention with replanning loops."""

from typing import Any, Optional
from shared.schemas import (
    EligibilityConfidence,
    EligibilityStatus,
    EvidenceGrounding,
    MatchResult,
)

DISCLAIMER_TEXT = (
    "Disclaimer: This evaluation is generated by an automated AI decision assistant based on available "
    "scheme guidelines. It does NOT constitute an official government eligibility guarantee or legal decision. "
    "Please verify all details on the official government portal before making financial commitments."
)


class Critic:
    """Performs safety, grounding, and hallucination checks on scheme matching results and triggers replanning."""

    def __init__(self):
        self.disclaimer = DISCLAIMER_TEXT

    def audit(
        self,
        match_results: list[MatchResult],
        evidence_records: Optional[list[EvidenceGrounding]] = None,
    ) -> dict[str, Any]:
        """Audits scheme recommendations for evidentiary grounding, portal reachability, and conflicting claims.

        Rules:
        1. Official link check: Must have a verifiable https/http portal URL.
        2. Evidence grounding: ELIGIBLE schemes must have satisfied reasons supported by criteria or evidence.
        3. Exclusion: Prunes ungrounded or contradictory schemes.
        4. Replanning Trigger: If more than 50% of results are ungrounded or invalid, marks requires_replanning=True.
        """
        flags: list[str] = []
        approved_results: list[MatchResult] = []
        confidence_assessments: dict[str, EligibilityConfidence] = {}
        evidence_map = {e.scheme_id: e for e in (evidence_records or [])}

        for result in match_results:
            scheme_valid = True
            confidence = EligibilityConfidence.NEEDS_OFFICIAL_VERIFICATION

            # Check 1: Official Portal URL
            if not result.official_url or not result.official_url.startswith("http"):
                flags.append(f"Pruned '{result.scheme_name}': Lacks valid official government URL.")
                scheme_valid = False

            # Check 2: Reason grounding for ELIGIBLE
            if result.status == EligibilityStatus.ELIGIBLE:
                if not result.satisfied_reasons:
                    flags.append(f"Pruned '{result.scheme_name}': Marked ELIGIBLE without satisfied reasons.")
                    scheme_valid = False
                else:
                    # Grounded
                    confidence = EligibilityConfidence.LIKELY_ELIGIBLE

            elif result.status == EligibilityStatus.ALMOST:
                if not result.missing_fields:
                    flags.append(f"Flagged '{result.scheme_name}': Marked ALMOST but specifies no missing fields.")
                confidence = EligibilityConfidence.POSSIBLY_ELIGIBLE

            elif result.status == EligibilityStatus.NOT_ELIGIBLE:
                if not result.disqualifying_reasons:
                    flags.append(f"Flagged '{result.scheme_name}': Marked NOT_ELIGIBLE without disqualifying reasons.")
                confidence = EligibilityConfidence.NOT_ELIGIBLE

            # Check 3: Evidentiary Grounding from Source
            if scheme_valid and result.scheme_id in evidence_map:
                ev = evidence_map[result.scheme_id]
                if not ev.is_grounded:
                    confidence = EligibilityConfidence.NEEDS_OFFICIAL_VERIFICATION
                    flags.append(f"Flagged '{result.scheme_name}': Lacks verified official source evidence.")

            if scheme_valid:
                confidence_assessments[result.scheme_id] = confidence
                approved_results.append(result)

        pruned_count = len(match_results) - len(approved_results)
        
        # Trigger replanning if invalid claims outnumber valid claims
        requires_replanning = False
        replanning_notes = []
        if len(match_results) > 0 and len(approved_results) == 0:
            requires_replanning = True
            replanning_notes.append("All retrieved candidate schemes were pruned for lack of grounding. Re-search with broadened criteria.")
        elif pruned_count > len(approved_results):
            requires_replanning = True
            replanning_notes.append("High proportion of ungrounded candidate schemes detected. Replanning needed.")

        return {
            "flags": flags,
            "is_valid": len(flags) == 0,
            "approved_results": approved_results,
            "pruned_count": pruned_count,
            "confidence_assessments": confidence_assessments,
            "requires_replanning": requires_replanning,
            "replanning_notes": replanning_notes,
            "disclaimer": self.disclaimer,
        }
